<?php
require_once __DIR__ . '/../includes/db.php'; require_admin();
if ($_SERVER['REQUEST_METHOD'] === 'POST') { $itemId=(int)($_POST['item_id']??0); $approved=(int)($_POST['approved']??0); $update=$pdo->prepare('UPDATE items SET is_approved = ? WHERE item_id = ?'); $update->execute([$approved,$itemId]); set_flash('success',$approved ? 'Item approved.' : 'Item hidden from public listings.'); redirect('admin/items.php'); }
$page_title='Manage Items'; $items=$pdo->query('SELECT i.item_id,i.item_name,i.status,i.is_approved,i.rental_price,u.name AS owner_name,c.category_name FROM items i INNER JOIN users u ON u.user_id=i.owner_id INNER JOIN categories c ON c.category_id=i.category_id ORDER BY i.created_at DESC')->fetchAll(); require_once __DIR__ . '/../includes/header.php'; require __DIR__ . '/_nav.php';
?>
<h1 class="h3 mb-4">Manage Items</h1><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover mb-0"><thead class="table-light"><tr><th class="ps-3">Item</th><th>Owner</th><th>Price</th><th>Listing</th><th class="pe-3 text-end">Action</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td class="ps-3"><strong><?php echo e($item['item_name']); ?></strong><div class="small text-muted"><?php echo e($item['category_name']); ?> | <?php echo e($item['status']); ?></div></td><td><?php echo e($item['owner_name']); ?></td><td><?php echo e(format_money($item['rental_price'])); ?></td><td><span class="badge text-bg-<?php echo $item['is_approved'] ? 'success' : 'secondary'; ?>"><?php echo $item['is_approved'] ? 'Approved' : 'Hidden'; ?></span></td><td class="pe-3 text-end"><form method="post"><input type="hidden" name="item_id" value="<?php echo e($item['item_id']); ?>"><input type="hidden" name="approved" value="<?php echo $item['is_approved'] ? '0' : '1'; ?>"><button class="btn btn-sm btn-outline-brand"><?php echo $item['is_approved'] ? 'Hide' : 'Approve'; ?></button></form></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__ . '/../includes/footer.php'; ?>
